"""Text of the ES Note written to a finding. English and Japanese."""
LABELS = {
    "en": {"title": "Jev triage suggestion", "disp": "Suggested disposition", "urg": "Suggested urgency",
           "conf": "confidence", "policy": "Policy notes", "expl": "Explanation", "foot":
           "Suggestion only. Set the final disposition and urgency in ES. Generated by TA-jev-triage (Jev %s, %s)."},
    "ja": {"title": "Jev トリアージ提案", "disp": "Disposition（提案）", "urg": "Urgency（提案）",
           "conf": "確信度", "policy": "判定ルールの注記", "expl": "説明", "foot":
           "提案のみです。最終的な Disposition と Urgency は ES で設定してください。TA-jev-triage により作成（Jev %s、%s）。"},
}
DISP = {"en": {"TP": "True Positive", "FP": "False Positive", "Benign": "Benign", "Undetermined": "Undetermined"},
        "ja": {"TP": "TP（真陽性）", "FP": "FP（誤検知）", "Benign": "Benign（正常な想定内の動作）", "Undetermined": "判別不可"}}


def build(rec, lang="en"):
    L = LABELS.get(lang, LABELS["en"])
    d = DISP.get(lang, DISP["en"]).get(rec.get("jev_disposition"), rec.get("jev_disposition"))
    lines = ["%s: %s (%s %s)" % (L["disp"], d, L["conf"], rec.get("jev_disposition_confidence")),
             "%s: %s (%s %s)" % (L["urg"], (rec.get("jev_urgency") or "").capitalize(), L["conf"], rec.get("jev_urgency_confidence"))]
    if rec.get("jev_policy"):
        lines.append("%s: %s" % (L["policy"], rec["jev_policy"]))
    if rec.get("jev_explanation") and rec.get("jev_explain_for") == rec.get("jev_time"):
        lines += ["", "%s:" % L["expl"], rec["jev_explanation"]]
    lines += ["", L["foot"] % (rec.get("jev_model"), rec.get("jev_questions"))]
    return L["title"], "\n".join(lines)
